/**
 * ARCHITECTURE DOCUMENTATION: CopilotProxy
 * =========================================
 *
 * This file implements the renderer-side proxy for communicating with the
 * Copilot SDK running in the Electron main process. It abstracts the IPC
 * communication and provides a clean API for React components.
 *
 * ## Usage Pattern:
 * ```typescript
 * // Initialize on app start
 * CopilotProxy.init();
 *
 * // Check if available
 * if (CopilotProxy.isAvailable) {
 *   // Start the client
 *   const started = await CopilotProxy.start();
 *
 *   // Create a session
 *   const sessionId = await CopilotProxy.createSession({ model: "gpt-4o" });
 *
 *   // Subscribe to events
 *   CopilotProxy.onMessageDelta.subscribe((sid, delta) => {
 *     // Handle streaming content
 *   });
 *
 *   // Send a message
 *   await CopilotProxy.send(sessionId, "Create a custom pig entity");
 * }
 * ```
 *
 * ## Related Files:
 * - src/electron/CopilotCommandHandler.ts - Main process handler
 * - src/core/IChatSession.ts - Type definitions
 * - src/UX/CopilotChatPanel.tsx - React chat UI
 */

import { EventDispatcher } from "ste-events";
import {
  ICopilotAuthStatus,
  ICopilotModel,
  ICopilotMessageDelta,
  ICopilotMessage,
  ICopilotToolStart,
  ICopilotToolEnd,
  CopilotEvent,
  IProjectSchemaSummary,
} from "./IChatSession";
import CreatorToolsHost, { HostType } from "../app/CreatorToolsHost";

/**
 * Interface for the Electron IPC API exposed via preload.
 */
interface ICopilotApi {
  invoke(channel: string, ...args: any[]): Promise<any>;
  receive(channel: string, callback: (...args: any[]) => void): void;
}

/**
 * Proxy class for communicating with Copilot SDK in main process.
 * Uses Electron IPC for communication.
 */
export default class CopilotProxy {
  // Event dispatchers for different event types
  private static _onMessageDelta = new EventDispatcher<string, string>();
  private static _onMessage = new EventDispatcher<string, ICopilotMessage>();
  private static _onToolStart = new EventDispatcher<string, ICopilotToolStart>();
  private static _onToolEnd = new EventDispatcher<string, ICopilotToolEnd>();
  private static _onSessionIdle = new EventDispatcher<string, void>();
  private static _onContextUpdated = new EventDispatcher<string, void>();
  private static _onError = new EventDispatcher<string, string>();

  private static _api: ICopilotApi | undefined;
  private static _initialized = false;
  private static _sdkAvailable: boolean | undefined;

  // Throttling for message deltas
  private static _deltaBuffer: Map<string, string> = new Map();
  private static _deltaFlushTimeout: ReturnType<typeof setTimeout> | undefined;
  private static readonly DELTA_FLUSH_INTERVAL_MS = 50;

  /**
   * Event fired when a streaming message delta is received.
   * Parameters: (sessionId, deltaContent)
   */
  public static get onMessageDelta() {
    return this._onMessageDelta.asEvent();
  }

  /**
   * Event fired when a complete assistant message is received.
   * Parameters: (sessionId, message)
   */
  public static get onMessage() {
    return this._onMessage.asEvent();
  }

  /**
   * Event fired when a tool invocation starts.
   * Parameters: (sessionId, toolStart)
   */
  public static get onToolStart() {
    return this._onToolStart.asEvent();
  }

  /**
   * Event fired when a tool invocation ends.
   * Parameters: (sessionId, toolEnd)
   */
  public static get onToolEnd() {
    return this._onToolEnd.asEvent();
  }

  /**
   * Event fired when a session becomes idle (processing complete).
   * Parameters: (sessionId)
   */
  public static get onSessionIdle() {
    return this._onSessionIdle.asEvent();
  }

  /**
   * Event fired when the project context is updated.
   * Parameters: (sessionId)
   */
  public static get onContextUpdated() {
    return this._onContextUpdated.asEvent();
  }

  /**
   * Event fired when an error occurs.
   * Parameters: (sessionId, errorMessage)
   */
  public static get onError() {
    return this._onError.asEvent();
  }

  /**
   * Whether the Copilot proxy is available (running in Electron).
   */
  public static get isAvailable(): boolean {
    return this._api !== undefined && CreatorToolsHost.hostType === HostType.electronWeb;
  }

  /**
   * Whether the Copilot SDK is available on the system.
   */
  public static get isSdkAvailable(): boolean | undefined {
    return this._sdkAvailable;
  }

  /**
   * Initialize the proxy. Should be called on app startup.
   */
  public static init(): void {
    if (this._initialized) {
      console.log("CopilotProxy: Already initialized");
      return;
    }

    // Get the preload-exposed API (window only exists in browser/Electron renderer context)
    // Use globalThis to safely check for window in Node.js context
    const globalAny = globalThis as any;
    if (typeof globalAny.window === "undefined") {
      console.log("CopilotProxy: window not available (Node.js context), skipping setup");
      return;
    }
    const windowAny = globalAny.window as any;
    console.log("CopilotProxy: Initializing, api available:", !!windowAny.api);
    console.log("CopilotProxy: invoke available:", typeof windowAny.api?.invoke);

    if (windowAny.api && typeof windowAny.api.invoke === "function") {
      this._api = windowAny.api;
      this._setupEventListener();
      console.log("CopilotProxy: API set up successfully");
    } else {
      console.log("CopilotProxy: API not available, skipping setup");
    }

    this._initialized = true;
  }

  /**
   * Set up the event listener for Copilot events from main process.
   */
  private static _setupEventListener(): void {
    if (!this._api) {
      return;
    }

    console.log("CopilotProxy: Setting up event listener for copilot:event");
    this._api.receive("copilot:event", (event: CopilotEvent) => {
      console.log("CopilotProxy: Received event from main process:", event.type);
      this._handleEvent(event);
    });
  }

  /**
   * Handle incoming events from main process.
   */
  private static _handleEvent(event: CopilotEvent): void {
    switch (event.type) {
      case "message_delta":
        this._handleMessageDelta(event.data);
        break;

      case "message":
        // Flush any pending deltas before dispatching the complete message
        // This prevents leftover deltas from appearing as a separate bubble
        this._flushDeltasForSession(event.data.sessionId);
        this._onMessage.dispatch(event.data.sessionId, event.data);
        break;

      case "tool_start":
        this._onToolStart.dispatch(event.data.sessionId, event.data);
        break;

      case "tool_end":
        this._onToolEnd.dispatch(event.data.sessionId, event.data);
        break;

      case "session_idle":
        // Flush any remaining deltas when session becomes idle
        this._flushDeltasForSession(event.sessionId);
        this._onSessionIdle.dispatch(event.sessionId, undefined);
        break;

      case "context_updated":
        this._onContextUpdated.dispatch(event.sessionId, undefined);
        break;

      case "error":
        this._onError.dispatch(event.sessionId, event.error);
        break;
    }
  }

  /**
   * Handle message delta with throttling to prevent UI jank.
   */
  private static _handleMessageDelta(data: ICopilotMessageDelta): void {
    // Accumulate deltas
    const existing = this._deltaBuffer.get(data.sessionId) || "";
    this._deltaBuffer.set(data.sessionId, existing + data.deltaContent);

    // Set up flush if not already pending
    if (!this._deltaFlushTimeout) {
      this._deltaFlushTimeout = setTimeout(() => {
        this._flushDeltas();
      }, this.DELTA_FLUSH_INTERVAL_MS);
    }
  }

  /**
   * Flush accumulated deltas to subscribers.
   */
  private static _flushDeltas(): void {
    this._deltaFlushTimeout = undefined;

    for (const [sessionId, content] of this._deltaBuffer.entries()) {
      if (content) {
        this._onMessageDelta.dispatch(sessionId, content);
      }
    }

    this._deltaBuffer.clear();
  }

  /**
   * Flush accumulated deltas for a specific session.
   * Called before dispatching a complete message to prevent leftover deltas
   * from appearing as a separate chat bubble.
   */
  private static _flushDeltasForSession(sessionId: string): void {
    const content = this._deltaBuffer.get(sessionId);
    if (content) {
      this._onMessageDelta.dispatch(sessionId, content);
      this._deltaBuffer.delete(sessionId);
    }

    // Cancel the pending timeout if buffer is now empty
    if (this._deltaBuffer.size === 0 && this._deltaFlushTimeout) {
      clearTimeout(this._deltaFlushTimeout);
      this._deltaFlushTimeout = undefined;
    }
  }

  /**
   * Start the Copilot client.
   * @returns Whether the client started successfully
   */
  public static async start(): Promise<{ success: boolean; error?: string; sdkAvailable: boolean }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron", sdkAvailable: false };
    }

    const result = await this._api.invoke("copilot:start");
    this._sdkAvailable = result.sdkAvailable;
    return result;
  }

  /**
   * Stop the Copilot client.
   */
  public static async stop(): Promise<{ success: boolean; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:stop");
  }

  /**
   * Create a new chat session.
   * @param config Session configuration
   * @returns Session ID if successful
   */
  public static async createSession(config?: {
    model?: string;
    projectSummary?: IProjectSchemaSummary;
    existingSessionId?: string;
  }): Promise<{ success: boolean; sessionId?: string; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:createSession", config || {});
  }

  /**
   * Send a message to a session.
   * @param sessionId The session ID
   * @param prompt The message to send
   */
  public static async send(sessionId: string, prompt: string): Promise<{ success: boolean; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:send", { sessionId, prompt });
  }

  /**
   * Abort the current session processing.
   * @param sessionId The session ID
   */
  public static async abort(sessionId: string): Promise<{ success: boolean; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:abort", { sessionId });
  }

  /**
   * Destroy a session.
   * @param sessionId The session ID
   */
  public static async destroySession(sessionId: string): Promise<{ success: boolean; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:destroySession", { sessionId });
  }

  /**
   * Get the authentication status.
   */
  public static async getAuthStatus(): Promise<ICopilotAuthStatus> {
    if (!this._api) {
      return {
        isAuthenticated: false,
        error: "Not running in Electron",
      };
    }

    return await this._api.invoke("copilot:getAuthStatus");
  }

  /**
   * List available models.
   */
  public static async listModels(): Promise<{ success: boolean; models?: ICopilotModel[]; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:listModels");
  }

  /**
   * Update the project context for a session.
   * @param sessionId The session ID
   * @param context The project schema summary
   */
  public static async updateContext(
    sessionId: string,
    context: IProjectSchemaSummary
  ): Promise<{ success: boolean; error?: string }> {
    if (!this._api) {
      return { success: false, error: "Not running in Electron" };
    }

    return await this._api.invoke("copilot:updateContext", { sessionId, context });
  }
}
